    static class Desktop extends JFrame {
        OrbitPanel view=new OrbitPanel();JLabel stats=new JLabel("Ready"),status=new JLabel("Solving...");JTextArea logs=new JTextArea(8,60);JSlider time=new JSlider(0,100000,0);JComboBox<String> frames=new JComboBox<>(new String[]{"Earth-Moon rotating","Barycentric inertial","Moon inertial close-up","Heliocentric overview"}),laps=new JComboBox<>(new String[]{"All 3 orbits","Orbit 1","Orbit 2","Orbit 3"});
        JTextField wet=new JTextField("40000"),dry=new JTextField("8000"),isp=new JTextField("450"),thrust=new JTextField("450"),phase=new JTextField("0");JCheckBox solar=new JCheckBox("Solar perturbation",true);JButton solve=new JButton("Solve again"),play=new JButton("Play");JComboBox<String> speed=new JComboBox<>(new String[]{"0.25","1","5","20"});boolean playing=false,setting=false;long last=System.nanoTime();
        Desktop(){super("钱学森的毕业课题 / 日地月三圈任务 · Java");setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);setLayout(new BorderLayout());JPanel top=new JPanel();top.add(frames);top.add(laps);JButton reset=new JButton("Reset camera");top.add(reset);JCheckBox enhance=new JCheckBox("Radii x3 (drawing only)");top.add(enhance);add(top,BorderLayout.NORTH);JPanel center=new JPanel(new BorderLayout());center.add(view,BorderLayout.CENTER);JPanel bottom=new JPanel(new BorderLayout()),buttons=new JPanel();buttons.add(play);String[] names={"Start","Moon / LOI","3 turns / TEI","Earth return"};for(int i=0;i<4;i++){final int j=i;JButton b=new JButton(names[i]);b.addActionListener(e->{if(view.mission==null)return;Mission m=view.mission;seek(j==0?0:j==1?m.arrival.b.t:j==2?m.orbit.t:m.home.b.t);});buttons.add(b);}buttons.add(speed);speed.setSelectedItem("1");bottom.add(buttons,BorderLayout.NORTH);bottom.add(time,BorderLayout.CENTER);center.add(bottom,BorderLayout.SOUTH);add(center,BorderLayout.CENTER);
            JPanel side=new SidePanel();side.setLayout(new BoxLayout(side,BoxLayout.Y_AXIS));side.setBorder(BorderFactory.createEmptyBorder(12,12,12,12));side.add(new JLabel("Adjustable example stage / 示例火箭"));JPanel inputs=new JPanel(new GridLayout(0,2,6,6));String[] labels={"Wet mass / kg","Dry mass / kg","Isp / s","Thrust / kN","Solar phase / deg"};JTextField[] fields={wet,dry,isp,thrust,phase};for(int i=0;i<fields.length;i++){inputs.add(new JLabel(labels[i]));inputs.add(fields[i]);}inputs.setMaximumSize(new Dimension(Integer.MAX_VALUE,160));side.add(inputs);side.add(solar);side.add(solve);side.add(status);side.add(stats);JButton export=new JButton("Export JSON + trajectory CSV");side.add(export);side.add(new JLabel("Red: Earth-relative speed increasing"));side.add(new JLabel("Blue: Earth-relative speed decreasing"));side.add(new JLabel("Bicircular approximation; not real ephemeris"));side.add(new JLabel("No Earth capture / atmospheric entry modeled"));logs.setEditable(false);logs.setLineWrap(true);JScrollPane logPane=new JScrollPane(logs);logPane.setPreferredSize(new Dimension(320,190));logPane.setMaximumSize(new Dimension(Integer.MAX_VALUE,220));side.add(logPane);for(Component component:side.getComponents())if(component instanceof JComponent)((JComponent)component).setAlignmentX(Component.LEFT_ALIGNMENT);JScrollPane scroll=new JScrollPane(side);scroll.setPreferredSize(new Dimension(380,700));add(scroll,BorderLayout.EAST);
            frames.addActionListener(e->{view.frame=frames.getSelectedIndex();view.reset();});laps.addActionListener(e->{view.lap=laps.getSelectedIndex();view.repaint();});reset.addActionListener(e->view.reset());enhance.addActionListener(e->{view.enhance=enhance.isSelected();view.repaint();});time.addChangeListener(e->{if(!setting&&view.mission!=null){view.time=time.getValue()/100000.*view.mission.home.b.t;playing=false;play.setText("Play");update();}});play.addActionListener(e->{if(view.mission==null)return;if(view.time>=view.mission.home.b.t)view.time=0;playing=!playing;play.setText(playing?"Pause":"Play");});solve.addActionListener(e->run());export.addActionListener(e->{if(view.mission==null)return;JFileChooser fc=new JFileChooser();fc.setFileSelectionMode(JFileChooser.DIRECTORIES_ONLY);if(fc.showSaveDialog(this)==JFileChooser.APPROVE_OPTION)try{writeOutputs(view.mission,fc.getSelectedFile().toPath());status.setText("Exported");}catch(IOException ex){status.setText(ex.getMessage());}});
            new javax.swing.Timer(33,e->{long now=System.nanoTime();if(playing&&view.mission!=null){view.time=Math.min(view.mission.home.b.t,view.time+(now-last)/1e9*view.mission.home.b.t/90*Double.parseDouble((String)speed.getSelectedItem()));if(view.time>=view.mission.home.b.t){playing=false;play.setText("Play");}update();}last=now;}).start();pack();setLocationByPlatform(true);run();}
        void seek(double t){view.time=t;playing=false;play.setText("Play");update();}
        void update(){Mission m=view.mission;if(m==null)return;double[] y=sample(m.states,view.time);String mode=mode(m,view.time);double force=mode.equals("coast")?0:m.o.thrust,turns=view.time<m.cap.t?0:view.time>=m.orbit.t?3:-(y[8]-m.cap.y[8])/(2*Math.PI);stats.setText(String.format(Locale.ROOT,"<html><br>Time: %.6f d / %s<br>Earth altitude: %.3f km<br>Moon altitude: %.3f km<br>Moon turns after LOI: %.9f<br><br>Mass: %.2f kg<br>Fuel: %.2f kg<br>Thrust: %.1f kN<br>Mass flow: %.3f kg/s<br>Engine acceleration: %.3f m/s²<br>Propulsive Δv: %.6f km/s<br>Earth speed: %.6f km/s<br>Earth speed derivative: %.5f m/s²<br>Solar tidal acceleration: %.4g m/s²<br><br>Event hM: %.6f km<br>Event hE: %.6f km<br>Final turns: %.12f<br>Current C: %.10f<br>Current ΔC: %.4g<br>C−C₀−W: %.4g<br>Max accepted balance defect: %.4g<br><br></html>",days(view.time),mode,altitude(y,false),altitude(y,true),turns,y[6],y[6]-m.o.dry,force/1000,force/(m.o.isp*G0),force/y[6],y[7],norm(relV(y,false))*V,speedRate(m,view.time,y),norm(solar(view.time,y,m.o))*D/(T*T)*1000,altitude(m.arrival.b.y,true),altitude(m.home.b.y,false),m.turns,jacobi(y),jacobi(y)-m.c0,jacobi(y)-m.c0-y[9],m.maxDefect));setting=true;time.setValue((int)(view.time/m.home.b.t*100000));setting=false;view.repaint();}
        void run(){playing=false;view.mission=null;view.repaint();stats.setText("Solving...");logs.setText("");Options o=new Options();try{o.mass=Double.parseDouble(wet.getText());o.dry=Double.parseDouble(dry.getText());o.isp=Double.parseDouble(isp.getText());o.thrust=Double.parseDouble(thrust.getText())*1000;o.phase=Double.parseDouble(phase.getText());o.sun=solar.isSelected();o.validate();}catch(Exception e){status.setText(e.getMessage());return;}solve.setEnabled(false);new SwingWorker<Mission,String>(){protected Mission doInBackground(){return SolarLunarMission.solve(o,s->publish(s));}protected void process(List<String> chunks){for(String s:chunks)logs.append(s+"\n");}protected void done(){solve.setEnabled(true);try{view.mission=get();status.setText("Converged / 3 lunar turns + Earth return");view.time=0;view.reset();update();}catch(Exception e){status.setText("Failed: "+e.getCause());}}}.execute();}
    }
    public static void main(String[] args)throws Exception{Locale.setDefault(Locale.ROOT);Options o=new Options();Path folder=Path.of("mission-output");boolean gui=false,preview=false;for(int i=0;i<args.length;i++)switch(args[i]){case "--gui":gui=true;break;case "--out":folder=Path.of(args[++i]);break;case "--mass":o.mass=Double.parseDouble(args[++i]);break;case "--dry":o.dry=Double.parseDouble(args[++i]);break;case "--isp":o.isp=Double.parseDouble(args[++i]);break;case "--thrust":o.thrust=Double.parseDouble(args[++i]);break;case "--phase":o.phase=Double.parseDouble(args[++i]);break;case "--no-sun":o.sun=false;break;case "--tight":o.rtol=2e-12;o.atol=2e-14;o.hmax=.00075;break;case "--preview":preview=true;break;default:throw new IllegalArgumentException("Unknown argument: "+args[i]);}if(gui){SwingUtilities.invokeLater(()->new Desktop().setVisible(true));return;}Mission m=solve(o,System.err::println);writeOutputs(m,folder);System.out.print(json(m));if(preview){OrbitPanel panel=new OrbitPanel();panel.mission=m;panel.time=m.orbit.t;panel.frame=2;panel.reset();panel.setSize(1200,800);BufferedImage image=new BufferedImage(1200,800,BufferedImage.TYPE_INT_RGB);Graphics2D g=image.createGraphics();panel.paint(g);g.dispose();ImageIO.write(image,"png",folder.resolve("java-orbit-preview.png").toFile());}}
